1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
44	const BASE_PREMIUM_RATES: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const CURSE_SURCHARGE_RATE = 0.5;
54	const HIGH_ENCHANTMENT_THRESHOLD = 5;
55	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
56	const LOYALTY_YEARS_THRESHOLD = 2;
57	const LOYALTY_DISCOUNT_RATE = 0.2;
58	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_PREMIUM = 60;
61	
62	const INSURANCE_VALUES: Record<string, number> = {
63	  sword: 1000,
64	  amulet: 600,
65	  staff: 800,
66	  potion: 400,
67	  rune: 250,
68	  moonstone: 250,
69	};
70	
71	// The office insures exactly the types it prices. Both the quote desk and the
72	// claim desk ask this same question, so it gets one answer here.
73	const isInsurableType = (type: string): boolean => type in BASE_PREMIUM_RATES;
74	
75	const validateInsurableType = (type: string): void => {
76	  if (!isInsurableType(type)) {
77	    throw new Error(`Unknown item type: ${type}`);
78	  }
79	};
80	
81	// A claim's damages are checked before any of them is priced, so a malformed
82	// claim is rejected outright rather than half-processed.
83	const validateDamage = (damage: Damage): void => {
84	  validateInsurableType(damage.itemType);
85	  if (damage.amount < 0) {
86	    throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
87	  }
88	};
89	
90	const DEDUCTIBLE_PER_DAMAGE = 100;
91	const CAP_MULTIPLIER = 2;
92	const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
93	const HALF_REIMBURSEMENT_RATE = 0.5;
94	const FULL_REIMBURSEMENT_RATE = 1;
95	
96	const countByType = (items: Item[]): Map<string, number> =>
97	  items.reduce(
98	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
99	    new Map<string, number>(),
100	  );
101	
102	const basePremiumForGroup = (type: string, itemCount: number): number =>
103	  itemCount === COMPONENT_BLOCK_SIZE
104	    ? COMPONENT_BLOCK_PREMIUM
105	    : itemCount * BASE_PREMIUM_RATES[type];
106	
107	// The policy base premium: the sum of all item base premiums, EXCLUDING
108	// item-specific surcharges. Policy-wide modifiers are percentages of this.
109	const policyBasePremium = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
112	    0,
113	  );
114	
115	const itemSurchargeRate = (item: Item): number =>
116	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
117	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
118	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
119	    : 0);
120	
121	const sumItemSurcharges = (items: Item[]): number =>
122	  items.reduce(
123	    (sum, item) =>
124	      sum + BASE_PREMIUM_RATES[item.type] * itemSurchargeRate(item),
125	    0,
126	  );
127	
128	// Premiums round in the MHPCO's favor, i.e. up.
129	const roundPremiumInMHPCOsFavor = (premium: number): number =>
130	  Math.ceil(premium);
131	
132	// Payouts round in the MHPCO's favor too — which for money leaving the office
133	// means down.
134	const roundPayoutInMHPCOsFavor = (payout: number): number =>
135	  Math.floor(payout);
136	
137	// What the office knows about the customer at the moment a quote is drawn up.
138	// Policy-wide modifiers are decided entirely by this context.
139	interface QuoteContext {
140	  customer: Customer;
141	  precedingQuoteCount: number;
142	}
143	
144	// Each policy-wide modifier is a signed percentage of the policy base premium:
145	// surcharges positive, discounts negative.
146	const policyWideModifierRates = ({
147	  customer,
148	  precedingQuoteCount,
149	}: QuoteContext): number[] => [
150	  FIRST_INSURANCE_SURCHARGE_RATE,
151	  ...(customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
152	    ? [-LOYALTY_DISCOUNT_RATE]
153	    : []),
154	  ...(precedingQuoteCount > 0 ? [-FOLLOW_UP_CONTRACT_DISCOUNT_RATE] : []),
155	];
156	
157	// Each rate is multiplied out against the base premium SEPARATELY and then
158	// summed. Summing the rates first and doing a single multiply is algebraically
159	// equal but not equal in floating point — 100 * (1 + 0.1) is 110.00000000000001
160	// — and rounding up turns that into a spurious extra gold piece.
161	const sumPolicyWideModifiers = (
162	  basePremium: number,
163	  context: QuoteContext,
164	): number =>
165	  policyWideModifierRates(context).reduce(
166	    (sum, rate) => sum + basePremium * rate,
167	    0,
168	  );
169	
170	const quote = (items: Item[], context: QuoteContext): StepResult => {
171	  items.forEach(({ type }) => validateInsurableType(type));
172	
173	  const basePremium = policyBasePremium(items);
174	
175	  return {
176	    premium: roundPremiumInMHPCOsFavor(
177	      basePremium +
178	        sumItemSurcharges(items) +
179	        sumPolicyWideModifiers(basePremium, context) +
180	        PROCESSING_FEE,
181	    ),
182	  };
183	};
184	
185	const policyInsuranceSum = (items: Item[]): number =>
186	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
187	
188	// How much of a damage the office reimburses, before the deductible.
189	//
190	// Full reimbursement is the default, which is also what the dragon-material
191	// clause grants — so that clause needs no branch of its own. The only clause
192	// that moves the rate off the default is high enchantment, and the spec makes
193	// it win outright when both apply, so testing it alone is the whole rule.
194	const reimbursementRate = (item: Item): number =>
195	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT
196	    ? HALF_REIMBURSEMENT_RATE
197	    : FULL_REIMBURSEMENT_RATE;
198	
199	// The deductible bites once per damaged item, after the rate, and never turns
200	// a payout negative — the office does not bill the customer for small damages.
201	const payoutForDamage = (damage: Damage, item: Item): number =>
202	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE);
203	
204	// Each damage entry claims one distinct insured item, so a matched item is
205	// consumed: two sword damages need two insured swords. Pairing every damage
206	// with its item up front separates "which item was hit" from "what is it worth",
207	// and lets a bad claim be rejected before any money is computed.
208	const matchDamagesToInsuredItems = (
209	  damages: Damage[],
210	  policyItems: Item[],
211	): [Damage, Item][] => {
212	  const unclaimed = [...policyItems];
213	
214	  return damages.map((damage) => {
215	    validateDamage(damage);
216	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
217	    if (index === -1) {
218	      throw new Error(
219	        `Damaged item is not covered by the policy: ${damage.itemType}`,
220	      );
221	    }
222	    const [damagedItem] = unclaimed.splice(index, 1);
223	
224	    return [damage, damagedItem];
225	  });
226	};
227	
228	const sumDamagePayouts = (damages: Damage[], policyItems: Item[]): number =>
229	  matchDamagesToInsuredItems(damages, policyItems).reduce(
230	    (sum, [damage, item]) => sum + payoutForDamage(damage, item),
231	    0,
232	  );
233	
234	// The cap is twice the policy's insurance sum, i.e. what the office will pay
235	// out over the policy's whole life. Premium modifiers do not move it.
236	const policyCap = (policyItems: Item[]): number =>
237	  policyInsuranceSum(policyItems) * CAP_MULTIPLIER;
238	
239	// A policy, with the cap it has left. The cap is consumed by every claim
240	// against the policy, so it lives with the policy rather than the claim.
241	interface Policy {
242	  items: Item[];
243	  remainingCap: number;
244	}
245	
246	// A claim never pays out more than the policy has cap left.
247	const claim = (
248	  incident: ClaimStep["incident"],
249	  policy: Policy,
250	): { result: StepResult; remainingCap: number } => {
251	  const desired = roundPayoutInMHPCOsFavor(
252	    sumDamagePayouts(incident.damages, policy.items),
253	  );
254	  const payout = Math.min(desired, policy.remainingCap);
255	  const remainingCap = policy.remainingCap - payout;
256	
257	  return { result: { payout, remainingCap }, remainingCap };
258	};
259	
260	// Policies the office has written so far, keyed by the step index of the quote
261	// that created them — that index is how a later claim step refers to a policy.
262	// The number of entries is also exactly the number of preceding quotes, which
263	// is what decides the follow-up contract discount; deriving it here keeps the
264	// two facts from drifting apart.
265	type PoliciesSoFar = Map<number, Policy>;
266	
267	export const runScenario = (scenario: Scenario): ScenarioResult => {
268	  const policies: PoliciesSoFar = new Map();
269	
270	  const results = scenario.steps.map((step, stepIndex) => {
271	    if (step.op === "claim") {
272	      const policy = policies.get(step.policy)!;
273	      const { result, remainingCap } = claim(step.incident, policy);
274	      policies.set(step.policy, { ...policy, remainingCap });
275	
276	      return result;
277	    }
278	
279	    const result = quote(step.items, {
280	      customer: scenario.customer,
281	      precedingQuoteCount: policies.size,
282	    });
283	    policies.set(stepIndex, {
284	      items: step.items,
285	      remainingCap: policyCap(step.items),
286	    });
287	
288	    return result;
289	  });
290	
291	  return { results };
292	};
