// A claim never pays out more than the policy has cap left.
const claim = (
  incident: ClaimStep["incident"],
  policy: Policy,
): { result: StepResult; remainingCap: number } => {
  const desired = roundPayoutInMHPCOsFavor(
    sumDamagePayouts(incident.damages, policy.items),
  );
  const payout = Math.min(desired, policy.remainingCap);
  const remainingCap = policy.remainingCap - payout;

  return { result: { payout, remainingCap }, remainingCap };
};

